// ── Hotspot Component ──
const Hotspot = memo(({ hotspot, onClick }) => (
  <button
    className="absolute flex items-center justify-center w-8 h-8 transition-all -translate-x-1/2 -translate-y-1/2 border-2 border-white rounded-full shadow-lg bg-red-500/70 hover:bg-red-500 focus:outline-none focus:ring-2 focus:ring-white"
