LocationCard.displayName = 'LocationCard';

// ── Interactive Viewer ──
const InteractiveViewer = memo(({
  selectedLocation,
  isFullscreen,
  setIsFullscreen,
  zoomLevel,
  handleZoomIn,
  handleZoomOut,
  resetView,
  showHotspots,
  setShowHotspots,
  showInfo,
  toggleInfo,
  audioEnabled,
  toggleAudio,
  viewMode,
  changeViewMode,
  chatOpen,
  setChatOpen,
  chatMessages,
  chatInput,
  setChatInput,
  handleChatSend,
}) => {
  const [rotation, setRotation] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [currentHotspot, setCurrentHotspot] = useState(null);
  const [showCopiedToast, setShowCopiedToast] = useState(false);
  
  const viewerRef = useRef(null);
  const wheelTimeoutRef = useRef(null);

  const location = useMemo(() => LOCATION_DATA[selectedLocation], [selectedLocation]);

  // Drag handlers
  const handleMouseDown = useCallback((e) => {
    e.preventDefault();
    setIsDragging(true);
    setDragStart({ x: e.clientX, y: e.clientY });
  }, []);

  const handleMouseMove = useCallback((e) => {
    if (!isDragging) return;
    
    const deltaX = e.clientX - dragStart.x;
    const deltaY = e.clientY - dragStart.y;
    
    setRotation((prev) => ({
      x: Math.max(-90, Math.min(90, prev.x + deltaY * 0.4)),
      y: (prev.y + deltaX * 0.4) % 360,
    }));
    
    setDragStart({ x: e.clientX, y: e.clientY });
  }, [isDragging, dragStart]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  // Wheel handler with ref-based timeout
  const handleWheel = useCallback((e) => {
    e.preventDefault();
    
    if (wheelTimeoutRef.current) clearTimeout(wheelTimeoutRef.current);
    
    wheelTimeoutRef.current = setTimeout(() => {
      if (e.deltaY < 0) handleZoomIn();
      else handleZoomOut();
    }, 10);
  }, [handleZoomIn, handleZoomOut]);

  // Hotspot click
  const handleHotspotClick = useCallback((hotspot) => {
    setCurrentHotspot(hotspot);
    const timer = setTimeout(() => setCurrentHotspot(null), 5000);
    return () => clearTimeout(timer);
  }, []);

  // Share
  const handleShare = useCallback(async () => {
    const url = location.url;
    
    if (navigator.share) {
      try {
        await navigator.share({
          title: `${selectedLocation} - Jharkhand AR/VR Tour`,
          text: location.description,
          url,
        });
      } catch (err) {
        if (err.name !== 'AbortError') copyToClipboard(url);
      }
    } else {
      copyToClipboard(url);
    }
  }, [selectedLocation, location]);

  const copyToClipboard = useCallback((text) => {
    navigator.clipboard?.writeText(text).then(() => {
      setShowCopiedToast(true);
      setTimeout(() => setShowCopiedToast(false), 2000);
    });
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e) => {
      switch (e.key) {
        case 'ArrowUp':
          setRotation(p => ({ ...p, x: Math.max(-90, p.x - 8) }));
          break;
        case 'ArrowDown':
          setRotation(p => ({ ...p, x: Math.min(90, p.x + 8) }));
          break;
        case 'ArrowLeft':
          setRotation(p => ({ ...p, y: p.y - 8 }));
          break;
        case 'ArrowRight':
          setRotation(p => ({ ...p, y: p.y + 8 }));
          break;
        case '+':
          handleZoomIn();
          break;
        case '-':
          handleZoomOut();
          break;
        case '0':
          resetView();
          break;
        case 'Escape':
          if (isFullscreen) setIsFullscreen(false);
          if (currentHotspot) setCurrentHotspot(null);
          break;
        case 'h':
          setShowHotspots(p => !p);
          break;
        case 'i':
          toggleInfo();
          break;
        case 'm':
          toggleAudio();
          break;
        case 'f':
          setIsFullscreen(p => !p);
          break;
        default:
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isFullscreen, currentHotspot, handleZoomIn, handleZoomOut, resetView, setIsFullscreen, setShowHotspots, toggleInfo, toggleAudio]);

  // Event listeners
  useEffect(() => {
    const viewer = viewerRef.current;
    if (!viewer) return;

    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }

    viewer.addEventListener('wheel', handleWheel, { passive: false });

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      viewer.removeEventListener('wheel', handleWheel);
    };
  }, [isDragging, handleMouseMove, handleMouseUp, handleWheel]);

  return (
    <div
      ref={viewerRef}
      className={`relative overflow-hidden select-none touch-none ${
        isFullscreen ? 'fixed inset-0 z-50' : 'h-[480px] rounded-2xl shadow-2xl'
      }`}
      style={{ 
        cursor: isDragging ? 'grabbing' : 'grab',
        background: '#0f172a',
        perspective: '1000px',
      }}
      onMouseDown={handleMouseDown}
      role="application"
      aria-label={`360° view of ${selectedLocation}`}
    >
      {/* Background Image */}
      <div
        className="absolute inset-0 bg-center bg-cover"
        style={{
          backgroundImage: `url(${location.image})`,
          transform: `perspective(1000px) rotateX(${rotation.x}deg) rotateY(${rotation.y}deg) scale(${zoomLevel})`,
          transition: isDragging ? 'none' : 'transform 0.15s cubic-bezier(0.2, 0, 0, 1)',
          filter: viewMode === 'AR' ? 'sepia(0.3) saturate(1.5) hue-rotate(5deg)' : 
                  viewMode === 'VR' ? 'brightness(1.1) contrast(1.1)' : 'brightness(0.95)',
          willChange: 'transform',
          backfaceVisibility: 'hidden',
          WebkitFontSmoothing: 'antialiased',
        }}
      />

      {/* VR Overlay */}
      {viewMode === 'VR' && (
        <>
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <div className="w-px h-full bg-white/30" />
          </div>
          <div className="absolute inset-0 pointer-events-none bg-gradient-to-r from-transparent via-black/10 to-transparent" />
        </>
      )}

      {/* Hotspots */}
      {showHotspots && location.hotspots.map((hotspot) => (
        <Hotspot key={hotspot.id} hotspot={hotspot} onClick={handleHotspotClick} />
      ))}

      {/* Hotspot Popup */}
      {currentHotspot && (
        <div
          className="absolute z-20 p-4 text-white -translate-x-1/2 -translate-y-1/2 border shadow-2xl w-72 top-1/2 left-1/2 bg-gray-900/95 backdrop-blur-md rounded-xl border-white/10"
          style={{ animation: 'fadeIn 0.2s cubic-bezier(0.2, 0, 0, 1)' }}
          role="dialog"
          aria-label="Hotspot information"
        >
          <button
            className="absolute text-lg top-2 right-3 text-white/60 hover:text-white"
            onClick={() => setCurrentHotspot(null)}
            aria-label="Close"
          >
            <IconClose />
          </button>
          <h4 className="pr-6 mb-2 text-base font-bold">{currentHotspot.title}</h4>
          <p className="text-sm leading-relaxed text-white/80">{currentHotspot.description}</p>
          <div className="mt-3 text-xs text-white/40">
            Click anywhere to close • Auto-closes in 5s
          </div>
        </div>
      )}

      {/* Top Controls */}
      <div className="absolute flex gap-2 top-4 right-4">
        <ControlButton 
          Icon={IconInfo}
          action={toggleInfo}
          title="Toggle info (I)"
          isActive={showInfo}
        />
        <ControlButton 
          Icon={IconHotspot}
          action={() => setShowHotspots(!showHotspots)}
          title="Toggle hotspots (H)"
          isActive={showHotspots}
        />
        <ControlButton 
          Icon={audioEnabled ? IconSound : IconSound}
          action={toggleAudio}
          title="Toggle audio (M)"
          isActive={audioEnabled}
        />
        <ControlButton 
          Icon={IconFullscreen}
          action={() => setIsFullscreen(!isFullscreen)}
          title={isFullscreen ? 'Exit fullscreen (F)' : 'Fullscreen (F)'}
          isActive={isFullscreen}
        />
        <ControlButton 
          Icon={IconShare}
          action={handleShare}
          title="Share this location"
        />
      </div>

      {/* Copy Toast */}
      {showCopiedToast && (
        <div className="absolute px-4 py-2 text-sm text-white bg-green-600 rounded-lg shadow-lg top-20 right-4">
          Link copied to clipboard!
        </div>
      )}

      {/* Info Panel */}
      {showInfo && (
        <div 
          className="absolute max-w-xs p-4 text-white border shadow-xl top-4 left-4 bg-gray-900/90 backdrop-blur-md rounded-xl border-white/10"
          style={{ animation: 'slideIn 0.2s ease-out' }}
        >
          <h4 className="mb-1 text-base font-bold">{selectedLocation}</h4>
          <p className="mb-3 text-xs leading-relaxed text-white/75">{location.description}</p>
          
          <div className="flex gap-2 mb-3">
            {['360', 'VR', 'AR'].map((mode) => (
              <button
                key={mode}
                className={`px-3 py-1 rounded-full text-xs font-medium transition-all ${
                  viewMode === mode
                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/30'
                    : 'bg-white/10 hover:bg-white/20 text-white/80'
                }`}
                onClick={() => changeViewMode(mode)}
                aria-pressed={viewMode === mode}
              >
                {mode}
              </button>
            ))}
          </div>
          
          <div className="grid grid-cols-2 gap-2 text-xs">
            <div className="px-2 py-1 rounded bg-white/5">
              <span className="text-white/40">Hotspots</span>
              <span className="block font-medium text-white">{location.hotspots.length}</span>
            </div>
            <div className="px-2 py-1 rounded bg-white/5">
              <span className="text-white/40">View</span>
              <span className="block font-medium text-white">{viewMode}</span>
            </div>
          </div>
        </div>
      )}

      {/* D-pad Navigation */}
      <div className="absolute p-2 border bottom-20 right-4 bg-gray-900/60 backdrop-blur-sm rounded-xl border-white/10">
        <div className="grid grid-cols-3 gap-1">
          <div></div>
          <button 
            className="flex items-center justify-center w-10 h-10 text-white transition-colors rounded-lg hover:bg-white/20 active:bg-white/30"
            onClick={() => setRotation(p => ({ ...p, x: Math.max(-90, p.x - 10) }))}
            aria-label="Look up"
          >▲</button>
          <div></div>
          
          <button 
            className="flex items-center justify-center w-10 h-10 text-white transition-colors rounded-lg hover:bg-white/20 active:bg-white/30"
            onClick={() => setRotation(p => ({ ...p, y: p.y - 10 }))}
            aria-label="Look left"
          >◀</button>
          <button 
            className="flex items-center justify-center w-10 h-10 text-white transition-colors rounded-lg hover:bg-white/20 active:bg-white/30"
            onClick={() => setRotation(p => ({ ...p, x: Math.min(90, p.x + 10) }))}
            aria-label="Look down"
          >▼</button>
          <button 
            className="flex items-center justify-center w-10 h-10 text-white transition-colors rounded-lg hover:bg-white/20 active:bg-white/30"
            onClick={() => setRotation(p => ({ ...p, y: p.y + 10 }))}
            aria-label="Look right"
          >▶</button>
        </div>
      </div>

      {/* Zoom Controls */}
      <div className="absolute flex flex-col gap-1 p-2 border bottom-20 left-4 bg-gray-900/60 backdrop-blur-sm rounded-xl border-white/10">
        <button
          onClick={handleZoomIn}
          className="flex items-center justify-center w-10 h-10 text-white transition-colors rounded-lg hover:bg-white/20 active:bg-white/30"
          aria-label="Zoom in"
        >
          <IconZoomIn />
        </button>
        <button
          onClick={resetView}
          className="flex items-center justify-center w-10 h-10 text-white transition-colors rounded-lg hover:bg-white/20 active:bg-white/30"
          aria-label="Reset view"
        >
          <IconReset />
        </button>
        <button
          onClick={handleZoomOut}
          className="flex items-center justify-center w-10 h-10 text-white transition-colors rounded-lg hover:bg-white/20 active:bg-white/30"
          aria-label="Zoom out"
        >
          <IconZoomOut />
        </button>
      </div>

      {/* Zoom Level Indicator */}
      <div className="absolute px-3 py-1 text-xs text-white border rounded-full bg-black/50 backdrop-blur-sm top-4 left-4 border-white/10">
        {Math.round(zoomLevel * 100)}%
      </div>

      {/* Bottom Hint Bar */}
      <div className="absolute flex items-center gap-3 px-4 py-2 text-xs text-white -translate-x-1/2 border rounded-full bottom-4 left-1/2 bg-gray-900/60 backdrop-blur-sm border-white/10 whitespace-nowrap">
        <span>Drag to look</span>
        <span className="opacity-40">|</span>
        <span>Arrows</span>
        <span className="opacity-40">|</span>
        <span>Scroll to zoom</span>
        <span className="opacity-40">|</span>
        <span>Tap hotspots</span>
      </div>

      {/* Chat Interface */}
      <div className="absolute z-20 bottom-20 right-4">
        {chatOpen ? (
          <div 
            className="flex flex-col overflow-hidden border shadow-2xl w-80 bg-gray-900/95 backdrop-blur-md border-white/10 rounded-2xl"
            style={{ height: '400px' }}
            role="dialog"
            aria-label="Chat with tour guide"
          >
            <div className="flex items-center justify-between px-4 py-3 border-b border-white/10 bg-blue-900/40">
              <div className="flex items-center gap-2">
                <span className="text-base">🤖</span>
                <span className="text-sm font-semibold text-white">Tour Guide</span>
                <span className="relative flex w-2 h-2">
                  <span className="absolute inline-flex w-full h-full bg-green-400 rounded-full opacity-75 animate-ping"></span>
                  <span className="relative inline-flex w-2 h-2 bg-green-400 rounded-full"></span>
                </span>
              </div>
              <button 
                className="transition-colors text-white/60 hover:text-white"
                onClick={() => setChatOpen(false)}
                aria-label="Close chat"
              >
                <IconClose />
              </button>
            </div>
            
            <div className="flex-1 p-3 space-y-3 overflow-y-auto">
              {chatMessages.map((m, i) => (
                <div
                  key={i}
                  className={`flex ${m.isBot ? 'justify-start' : 'justify-end'}`}
                >
                  <div
                    className={`text-xs px-3 py-2 rounded-2xl max-w-[85%] leading-relaxed ${
                      m.isBot
                        ? 'bg-blue-800/50 text-white rounded-tl-none'
                        : 'bg-blue-600 text-white rounded-tr-none'
                    }`}
                  >
                    {m.text}
                  </div>
                </div>
              ))}
            </div>
            
            <form onSubmit={handleChatSend} className="flex gap-2 p-3 border-t border-white/10">
              <input
                className="flex-1 px-3 py-2 text-xs text-white transition-all border rounded-lg outline-none bg-white/10 placeholder-white/40 border-white/10 focus:border-blue-400 focus:bg-white/20"
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                placeholder="Ask about this place..."
                aria-label="Chat input"
              />
              <button 
                type="submit" 
                className="px-3 py-2 text-xs font-medium text-white transition bg-blue-600 rounded-lg hover:bg-blue-500 disabled:opacity-50"
                disabled={!chatInput.trim()}
              >
                <IconSend />
              </button>
            </form>
          </div>
        ) : (
          <button
            onClick={() => setChatOpen(true)}
            className="flex items-center gap-2 px-4 py-3 text-sm text-white transition-all bg-blue-600 border rounded-full shadow-lg hover:bg-blue-500 hover:shadow-blue-500/30 hover:shadow-xl border-blue-400/30"
            aria-label="Open chat"
          >
            💬 <span className="font-medium">Ask Guide</span>
            <span className="px-1.5 py-0.5 text-xs bg-white/20 rounded-full">AI</span>
          </button>
        )}
      </div>
    </div>
  );
});

InteractiveViewer.displayName = 'InteractiveViewer';

// ── Info Card ──
const InfoCard = memo(({ emoji, title, items }) => (
  <div className="p-5 transition-all border bg-white/5 border-white/10 rounded-2xl backdrop-blur-sm hover:bg-white/10">
    <h4 className="flex items-center gap-2 mb-3 font-bold text-white">
      <span className="text-xl">{emoji}</span>
      <span>{title}</span>
    </h4>
    <ul className="space-y-2">
      {items.map((item, i) => (
        <li key={i} className="flex items-center gap-2 text-xs text-slate-400">
          <span className="w-1 h-1 bg-blue-400 rounded-full" />
          {item}
        </li>
      ))}
    </ul>
  </div>
));

InfoCard.displayName = 'InfoCard';

// ── Main ARVR Component ──
const ARVR = () => {
  const [selectedLocation, setSelectedLocation] = useState('Betla National Park');
  const [previewUrl, setPreviewUrl] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showInfo, setShowInfo] = useState(true);
  const [viewMode, setViewMode] = useState('360');
  const [zoomLevel, setZoomLevel] = useState(1);
  const [showHotspots, setShowHotspots] = useState(true);
  const [audioEnabled, setAudioEnabled] = useState(false);
  const [showTutorial, setShowTutorial] = useState(true);
  const [chatOpen, setChatOpen] = useState(false);
  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState(() => [
    { text: 'Welcome to the virtual tour! Ask me anything about this location.', isBot: true },
  ]);

  const handleShowPreview = useCallback(() => {
    setPreviewUrl(LOCATION_DATA[selectedLocation].url);
    setIsLoading(true);
    
    setTimeout(() => {
      setIsLoading(false);
    }, 1800);
  }, [selectedLocation]);

  const toggleInfo = useCallback(() => setShowInfo(p => !p), []);
  const toggleAudio = useCallback(() => setAudioEnabled(p => !p), []);
  
  const handleZoomIn = useCallback(() => {
    setZoomLevel(p => Math.min(p + 0.15, 2.5));
  }, []);
  
  const handleZoomOut = useCallback(() => {
    setZoomLevel(p => Math.max(p - 0.15, 0.5));
  }, []);
  
  const resetView = useCallback(() => {
    setZoomLevel(1);
  }, []);

  const changeViewMode = useCallback((mode) => {
    setViewMode(mode);
    if (navigator.vibrate) navigator.vibrate(50);
  }, []);

  const handleChatSend = useCallback((e) => {
    e.preventDefault();
    if (!chatInput.trim()) return;
    
    const userMsg = { text: chatInput, isBot: false };
    setChatMessages(prev => [...prev, userMsg]);
    
    const question = chatInput.toLowerCase();
    setChatInput('');
    
    setTimeout(() => {
      let response = '';
      
      if (question.includes('best time') || question.includes('when to visit')) {
        response = `The best time to visit ${selectedLocation} is from October to March when the weather is pleasant. Avoid monsoon season.`;
      } else if (question.includes('how to reach') || question.includes('transport')) {
        response = `${selectedLocation} is well-connected by road. Nearest railway station is Ranchi Junction (45-60 km away).`;
      } else if (question.includes('history')) {
        response = `${selectedLocation} has rich historical and cultural significance. It's a key destination in Jharkhand tourism.`;
      } else if (question.includes('wildlife') || question.includes('animals')) {
        response = `You might spot various wildlife including elephants, tigers, leopards, and many bird species here!`;
      } else if (question.includes('hello') || question.includes('hi')) {
        response = `Hello! I'm your AI tour guide. Ask me about attractions, best times to visit, or local culture!`;
      } else {
        response = `${selectedLocation} is a beautiful destination. Would you like to know about specific attractions or visiting tips?`;
      }
      
      setChatMessages(prev => [...prev, { text: response, isBot: true }]);
    }, 800);
  }, [selectedLocation, chatInput]);

  const selectedColor = LOCATION_DATA[selectedLocation].color;

  return (
    <div className={`min-h-screen bg-gradient-to-br from-slate-900 via-blue-950 to-slate-900 ${isFullscreen ? 'p-0' : 'p-6'}`}>
      <style>{`
        @keyframes float {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-10px); }
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translate(-50%, -50%) scale(0.95); }
          to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
        }
        @keyframes slideIn {
          from { opacity: 0; transform: translateX(-20px); }
          to { opacity: 1; transform: translateX(0); }
        }
        @keyframes hotspotPulse {
          0%, 100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.6); }
          50% { box-shadow: 0 0 0 12px rgba(239, 68, 68, 0); }
        }
        @keyframes progress {
          0% { width: 0%; }
          50% { width: 70%; }
          100% { width: 100%; }
        }
        .animate-progress {
          animation: progress 1.8s ease-in-out forwards;
        }
      `}</style>

      {!isFullscreen && (
        <>
          {/* Header */}
          <div className="flex items-center justify-between mb-8">
            <div>
              <h1 className="text-4xl font-bold tracking-tight text-white">
                Jharkhand AR/VR Tour
              </h1>
              <p className="mt-2 text-sm text-slate-400">
                Immersive virtual tours of Jharkhand's most stunning destinations
              </p>
            </div>
            <button
              onClick={() => setShowTutorial(p => !p)}
              className="px-5 py-2.5 text-sm font-medium text-blue-300 transition-all border bg-blue-900/40 border-blue-700/40 rounded-xl hover:bg-blue-800/40"
            >
              {showTutorial ? 'Hide Tips' : 'Show Guide'}
            </button>
          </div>

          {/* Tutorial */}
          {showTutorial && (
            <div className="relative p-4 mb-6 overflow-hidden border rounded-2xl bg-gradient-to-r from-blue-900/30 to-purple-900/30 border-blue-700/30">
              <div className="relative flex items-start gap-4">
                <span className="text-3xl">💡</span>
                <div className="flex-1">
                  <h3 className="mb-2 font-semibold text-blue-200">Pro Tips:</h3>
                  <div className="grid grid-cols-1 gap-2 text-sm text-blue-200/80 md:grid-cols-2">
                    <div>Arrow keys to navigate</div>
                    <div>+/- to zoom</div>
                    <div>0 to reset view</div>
                    <div>F for fullscreen</div>
                    <div>Click glowing dots for info</div>
                    <div>Drag to look around</div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Location Cards */}
          <div className="grid grid-cols-2 gap-3 mb-6 sm:grid-cols-3 lg:grid-cols-5">
            {Object.keys(LOCATION_DATA).map((loc) => (
              <LocationCard
                key={loc}
                location={loc}
                isSelected={loc === selectedLocation}
                onClick={() => setSelectedLocation(loc)}
              />
            ))}
          </div>

          {/* Start Button */}
          <div className="flex flex-wrap items-center gap-4 mb-6">
            <button
              onClick={handleShowPreview}
              className="flex items-center gap-3 px-8 py-4 font-semibold text-white transition-all shadow-lg bg-gradient-to-r from-blue-600 to-blue-500 hover:from-blue-500 hover:to-blue-400 rounded-xl shadow-blue-600/30"
            >
              <span>Start Experience</span>
            </button>
            
            <div className="flex gap-2 ml-auto">
              <span className="px-3 py-1 text-xs border rounded-full bg-white/5 border-white/10 text-slate-300">
                {LOCATION_DATA[selectedLocation].hotspots.length} Hotspots
              </span>
              <span className="px-3 py-1 text-xs border rounded-full bg-white/5 border-white/10 text-slate-300">
                {viewMode} Mode
              </span>
            </div>
          </div>
        </>
      )}

      {/* Loading State */}
      {isLoading ? (
        <div className="h-[480px] rounded-2xl overflow-hidden relative flex flex-col items-center justify-center bg-slate-800 border border-white/5">
          <div className="relative mb-8">
            <div className="w-20 h-20 border-4 rounded-full border-blue-500/30 border-t-blue-500 animate-spin" />
          </div>
          
          <p className="z-10 mb-2 text-xl font-bold text-white">{selectedLocation}</p>
          <p className="z-10 mb-4 text-sm text-slate-400">Loading immersive environment...</p>
          
          <div className="w-64 h-2 overflow-hidden rounded-full bg-white/10">
            <div className="h-full rounded-full bg-gradient-to-r from-blue-500 to-purple-500 animate-progress" />
          </div>
        </div>
      ) : previewUrl ? (
        <InteractiveViewer
          selectedLocation={selectedLocation}
          isFullscreen={isFullscreen}
          setIsFullscreen={setIsFullscreen}
          zoomLevel={zoomLevel}
          handleZoomIn={handleZoomIn}
          handleZoomOut={handleZoomOut}
          resetView={resetView}
          showHotspots={showHotspots}
          setShowHotspots={setShowHotspots}
          showInfo={showInfo}
          toggleInfo={toggleInfo}
          audioEnabled={audioEnabled}
          toggleAudio={toggleAudio}
          viewMode={viewMode}
          changeViewMode={changeViewMode}
          chatOpen={chatOpen}
          setChatOpen={setChatOpen}
          chatMessages={chatMessages}
          chatInput={chatInput}
          setChatInput={setChatInput}
          handleChatSend={handleChatSend}
        />
      ) : (
        <div className="h-[480px] rounded-2xl border border-white/5 bg-slate-800/50 flex flex-col items-center justify-center text-center p-8">
          <div className="mb-6 text-7xl" style={{ animation: 'float 3s ease-in-out infinite' }}>
            {selectedLocation === 'Betla National Park' && '🐯'}
            {selectedLocation === 'Hundru Falls' && '💧'}
            {selectedLocation === 'Jonha Falls' && '🌊'}
            {selectedLocation === 'Baidyanath Dham' && '🛕'}
            {selectedLocation === 'Patratu Valley' && '🏔️'}
          </div>
          
          <h2 className="mb-3 text-3xl font-bold text-white">
            {selectedLocation}
          </h2>
          
          <p className="max-w-md mb-6 text-sm leading-relaxed text-slate-400">
            {LOCATION_DATA[selectedLocation].description}
          </p>
          
          <button
            onClick={handleShowPreview}
            className="px-8 py-3 text-white transition-all bg-blue-600 rounded-xl hover:bg-blue-500"
          >
            Start Virtual Tour →
          </button>
        </div>
      )}

      {/* Info Cards */}
      {!isFullscreen && (
        <div className="grid grid-cols-1 gap-4 mt-8 md:grid-cols-3">
          <InfoCard
            emoji="🎮"
            title="Navigation"
            items={[
              'Drag or arrow keys to look around',
              'Scroll wheel or +/- keys to zoom',
              'Click hotspots for detailed info',
              'Press 0 to reset view',
            ]}
          />
          <InfoCard
            emoji="📱"
            title="Device Support"
            items={[
              'Desktop: Mouse + keyboard',
              'Mobile: Touch gestures',
              'VR headsets supported',
              'Spatial audio ready',
            ]}
          />
          <InfoCard
            emoji="⚡"
            title="Pro Features"
            items={[
              'AI tour guide in chat',
              '4+ hotspots per location',
              '360°, VR & AR modes',
              'Share locations easily',
            ]}
          />
        </div>
      )}
    </div>
  );
};

export default ARVR;
